* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  width: 100%;
  min-width: 0;
  font-family: "Segoe UI", Inter, -apple-system, BlinkMacSystemFont, sans-serif;
  background: transparent;
}

body {
  overflow-x: hidden;
}

/* Dashboard grid */
.dashboard-container {
  display: grid;
  width: 100%;
  padding: 2px;
  align-items: start;
}

/* Main tile */
.dashboard-tile {
  min-width: 0;
  min-height: 68px;
  height: auto;
  align-self: start;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 6px 8px;
  background: #ffffff;
  border: 1px solid #dce7f5;
  border-radius: 5px;
  box-shadow: 0 1px 2px rgba(30, 64, 110, 0.02);
  cursor: pointer;
  user-select: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
}

.dashboard-tile:hover {
  border-color: #b8cde8;
  box-shadow: 0 2px 6px rgba(39, 76, 125, 0.06);
}

.dashboard-tile:active {
  transform: translateY(1px);
}

/* Parent tile containing sub-tiles */
.dashboard-tile.has-subtiles {
  justify-content: flex-start;
  padding-top: 6px;
  padding-bottom: 6px;
}

/* Expanded parent tile */
.dashboard-tile.is-expanded {
  height: auto;
  min-height: 68px;
  justify-content: flex-start;
  border-color: #cbdcf3;
  background: #ffffff;
  z-index: 1;
}

/* Header: icon + title/count + arrow */
.tile-header-container {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 20px;
  align-items: center;
  column-gap: 6px;
  width: 100%;
  min-width: 0;
  flex-shrink: 0;
}

/* Icon circle */
.tile-icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  color: var(--icon-color, #1677f5);
  background: var(--icon-bg, #eaf3ff);
  border: 1px solid var(--icon-border, #d5e6ff);
  border-radius: 50%;
}

.tile-icon {
  display: block;
  width: 14.5px;
  height: 14.5px;
}

/* Main tile text */
.tile-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  gap: 1px;
}

.tile-name {
  margin: 0;
  color: #193253;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.1px;
  text-transform: none;
  overflow-wrap: anywhere;
}

.tile-count {
  margin: 0;
  color: #10284b;
  font-size: 15.5px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.3px;
  font-variant-numeric: tabular-nums;
}

/* Standard right-facing arrow for tiles without sub-tiles */
.tile-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 26px;
  padding: 0;
  color: #8299ba;
  background: transparent;
  border: none;
  border-radius: 4px;
  flex-shrink: 0;
  transition: color 0.18s ease, background-color 0.18s ease, transform 0.18s ease;
}

.tile-arrow svg {
  display: block;
  width: 10px;
  height: 12px;
}

.dashboard-tile:hover > .tile-header-container .tile-arrow {
  color: #2563eb;
}

/* Dropdown toggle for tiles with sub-tiles */
.tile-arrow.dropdown-toggle {
  width: 26px;
  height: 26px;
  justify-self: end;
  cursor: pointer;
  outline: none;
}

.dropdown-toggle:hover {
  color: #2563eb;
  background: #edf4ff;
}

.dropdown-toggle:focus-visible {
  outline: 2px solid #4789ed;
  outline-offset: 2px;
}

.dropdown-toggle .chevron-icon {
  width: 15px;
  height: 15px;
  transition: transform 0.22s ease;
}

/* Rotate the dropdown arrow when expanded */
.dropdown-toggle.is-open .chevron-icon {
  transform: rotate(180deg);
}

.dropdown-toggle.is-open {
  color: #2563eb;
  background: #f0f6ff;
}

/* Selected main tile */
.dashboard-tile.is-selected {
  border-color: #4789ed;
  background: #f4f8ff;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.14);
}

/* Keep the dropdown visible on selected tiles */
.dashboard-tile.is-selected .tile-arrow {
  color: #2563eb;
}

/* Sub-tile section: hidden by default */
.sub-tiles-container {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 100%;
  min-width: 0;
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

/* Show sub-tiles only when the parent is expanded */
.sub-tiles-container.is-open {
  display: flex;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid #e7edf5;
}

/* Individual sub-tile */
.sub-tile {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-width: 0;
  flex-shrink: 0;
  padding: 6px 8px;
  background: #f8faff;
  border: 1px solid #e1e9f4;
  border-radius: 4px;
  cursor: pointer;
  transition: border-color 0.18s ease, background-color 0.18s ease;
}

.sub-tile:hover {
  background: #f0f6ff;
  border-color: #c7d9f0;
}

.sub-tile.is-selected {
  background: #edf5ff;
  border-color: #4789ed;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.12);
}

/* Sub-tile name */
.sub-tile-name {
  flex: 1;
  min-width: 0;
  color: #536783;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

/* Sub-tile count */
.sub-tile-count {
  flex-shrink: 0;
  margin-left: auto;
  color: #142b4d;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

/* Loading */
.dashboard-loading {
  padding: 10px;
  color: #64748b;
  text-align: center;
  font-size: 11px;
}

/* Responsive sizing: tablets and smaller screens */
@media (max-width: 1100px) {
  .dashboard-tile {
    padding: 5px 6px;
  }
  .tile-header-container {
    grid-template-columns: 25px minmax(0, 1fr) 20px;
    column-gap: 5px;
  }
  .tile-icon-wrapper {
    width: 25px;
    height: 25px;
  }
  .tile-icon {
    width: 13px;
    height: 13px;
  }
  .tile-name {
    font-size: 11px;
  }
  .tile-count {
    font-size: 14px;
  }
  .sub-tile {
    padding: 5px 7px;
  }
  .sub-tile-name {
    font-size: 11px;
  }
  .sub-tile-count {
    font-size: 12px;
  }
}
/* Responsive sizing: mobile screens */
@media (max-width: 700px) {
  .dashboard-container {
    padding: 2px;
    gap: 4px;
  }
  .dashboard-tile {
    min-height: 62px;
    padding: 4px 5px;
  }
  .dashboard-tile.has-subtiles {
    padding-top: 5px;
    padding-bottom: 5px;
  }
  .tile-header-container {
    grid-template-columns: 23px minmax(0, 1fr) 20px;
    column-gap: 4px;
  }
  .tile-icon-wrapper {
    width: 23px;
    height: 23px;
  }
  .tile-icon {
    width: 12px;
    height: 12px;
  }
  .tile-name {
    font-size: 10px;
  }
  .tile-count {
    font-size: 13px;
  }
  .tile-info {
    gap: 1px;
  }
  .tile-arrow.dropdown-toggle {
    width: 24px;
    height: 24px;
  }
  .dropdown-toggle .chevron-icon {
    width: 14px;
    height: 14px;
  }
  .sub-tiles-container.is-open {
    gap: 4px;
    margin-top: 5px;
    padding-top: 5px;
  }
  .sub-tile {
    padding: 5px 6px;
    gap: 6px;
  }
  .sub-tile-name {
    font-size: 10px;
    line-height: 1.3;
  }
  .sub-tile-count {
    font-size: 11px;
  }
}

