  font-variant-numeric: tabular-nums;
}

/* Standard right-facing arrow for tiles without sub-tiles */
.tile-arrow {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 20px;
  height: 26px;
  padding: 0;

  color: #8299ba;
  background: transparent;
  border: none;
  border-radius: 4px;
  flex-shrink: 0;

