    color 0.18s ease,
    background-color 0.18s ease,
    transform 0.18s ease;
}

.tile-arrow svg {
  display: block;
  width: 10px;
  height: 12px;
}

.dashboard-tile:hover > .tile-header-container .tile-arrow {
  color: #2563eb;
}

/* Dropdown toggle for tiles with sub-tiles */
.tile-arrow.dropdown-toggle {
  width: 26px;
  height: 26px;
  justify-self: end;
  cursor: pointer;
  outline: none;
}

.dropdown-toggle:hover {
  color: #2563eb;
  background: #edf4ff;
}

.dropdown-toggle:focus-visible {
  outline: 2px solid #4789ed;
  outline-offset: 2px;
}

.dropdown-toggle .chevron-icon {
  width: 15px;
  height: 15px;
  transition: transform 0.22s ease;
}

/* Rotate the dropdown arrow when expanded */
.dropdown-toggle.is-open .chevron-icon {
  transform: rotate(180deg);
}

.dropdown-toggle.is-open {
  color: #2563eb;
  background: #f0f6ff;
}

/* Selected main tile */
.dashboard-tile.is-selected {
  border-color: #4789ed;
  background: #f4f8ff;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.14);
}

/* Keep the dropdown visible on selected tiles */
.dashboard-tile.is-selected .tile-arrow {
  color: #2563eb;
}

/* Sub-tile section: hidden by default */
.sub-tiles-container {
  display: none;
  flex-direction: column;
  gap: 5px;

  width: 100%;
  min-width: 0;

  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

/* Show sub-tiles only when the parent is expanded */
.sub-tiles-container.is-open {
  display: flex;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid #e7edf5;
}

/* Individual sub-tile */
.sub-tile {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 8px;

  width: 100%;
  min-width: 0;
  flex-shrink: 0;

  padding: 6px 8px;

  background: #f8faff;
  border: 1px solid #e1e9f4;
  border-radius: 4px;
  cursor: pointer;

  transition:
    border-color 0.18s ease,
    background-color 0.18s ease;
}

.sub-tile:hover {
  background: #f0f6ff;
  border-color: #c7d9f0;
}

.sub-tile.is-selected {
  background: #edf5ff;
  border-color: #4789ed;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.12);
}

/* Sub-tile name */
.sub-tile-name {
  flex: 1;
  min-width: 0;

  color: #536783;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.35;

  overflow-wrap: anywhere;
}

/* Sub-tile count */
.sub-tile-count {
  flex-shrink: 0;
  margin-left: auto;

  color: #142b4d;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
