/* Loading */
.dashboard-loading {
  padding: 10px;
  color: #64748b;
  text-align: center;
  font-size: 11px;
}

/* Responsive sizing: tablets and smaller screens */
@media (max-width: 1100px) {
  .dashboard-tile {
    padding: 5px 6px;
  }

  .tile-header-container {
    grid-template-columns: 25px minmax(0, 1fr) 20px;
