  .sub-tile-count {
    font-size: 12px;
  }
}

/* Responsive sizing: mobile screens */
@media (max-width: 700px) {
  .dashboard-container {
    padding: 2px;
    gap: 4px;
  }

  .dashboard-tile {
    min-height: 62px;
    padding: 4px 5px;
  }

  .dashboard-tile.has-subtiles {
    padding-top: 5px;
