    column-gap: 4px;
  }

  .tile-icon-wrapper {
    width: 23px;
    height: 23px;
  }

  .tile-icon {
    width: 12px;
    height: 12px;
  }

  .tile-name {
    font-size: 10px;
  }

  .tile-count {
    font-size: 13px;
  }

  .tile-info {
    gap: 1px;
  }

  .tile-arrow.dropdown-toggle {
    width: 24px;
    height: 24px;
  }

  .dropdown-toggle .chevron-icon {
    width: 14px;
    height: 14px;
  }

  .sub-tiles-container.is-open {
    gap: 4px;
    margin-top: 5px;
    padding-top: 5px;
  }

  .sub-tile {
    padding: 5px 6px;
    gap: 6px;
  }

  .sub-tile-name {
    font-size: 10px;
    line-height: 1.3;
  }

  .sub-tile-count {
    font-size: 11px;
  }
}

