/* Automatically choose an icon based on the tile name. */
function getTileIcon(name = "") {
  const n = name.toLowerCase();

  if (n.includes("oa/arc") || n.includes("qa/arc")) return "document";
  if (n.includes("consistency") || n.includes("vendor")) return "users";
  if (n.includes("rfq")) return "send";

  if (n.includes("bid submission") || n.includes("commercial")) {
    return n.includes("commercial") ? "chart" : "gavel";
  }

  if (n.includes("technical")) return "shield";
  if (n.includes("e-nfa") || n.includes("approval")) return "approval";
  if (n.includes("created")) return "box";
  if (n.includes("released") || n.includes("purchase order")) return "truck";
  if (n.includes("manual") || n.includes("route")) return "route";

  return "document";
}

/* Pastel icon colors. */
const TILE_COLORS = [
  { bg: "#eaf3ff", border: "#d5e6ff", color: "#1677f5" },
  { bg: "#e5f9ef", border: "#c9f0dc", color: "#14965d" },
