  return (
    <div
      className="tile-icon-wrapper"
      style={{
        "--icon-bg": palette.bg,
        "--icon-border": palette.border,
        "--icon-color": palette.color
      }}
    >
      <svg
        className="tile-icon"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.9"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
      >
        {ICONS[iconName]}
      </svg>
    </div>
  );
}

function ChevronIcon({ expanded }) {
  return (
    <svg
      className="chevron-icon"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="m6 9 6 6 6-6"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function App() {
  const [model, setModel] = React.useState(appsmith.model || {});
  const [expandedTile, setExpandedTile] = React.useState(null);

  React.useEffect(() => {
    const handleModelChange = (newModel) => {
      if (newModel) setModel(newModel);
    };

    appsmith.onModelChange(handleModelChange);
  }, []);

  /* Preserve the existing filter and Appsmith event behavior. */
  const handleTileClick = (filterValue, e) => {
    if (e) e.stopPropagation();

    if (filterValue) {
      if (appsmith.updateModel) {
        const newFilter =
          model.selectedFilter === filterValue ? "" : filterValue;

        appsmith.updateModel({ clickedFilter: newFilter });
      }

      if (appsmith.triggerEvent) {
        appsmith.triggerEvent("onTileClick");
      }
    }
  };

  /* Expand or collapse a parent tile without triggering its filter. */
  const toggleSubTiles = (tileKey, e) => {
    e.stopPropagation();

    setExpandedTile((current) =>
      current === tileKey ? null : tileKey
    );
  };

  if (!model.tiles || !Array.isArray(model.tiles)) {
    return (
      <div className="dashboard-loading">
        Loading Dashboard Metrics...
      </div>
    );
  }

  const sortedTiles = [...model.tiles].sort(
    (a, b) => (a.SortOrder || 0) - (b.SortOrder || 0)
  );

  return (
    <div
      className="dashboard-container"
      style={{
        gridTemplateColumns: `repeat(${model.layout?.columns || 5}, minmax(0, 1fr))`,
        gridAutoRows: "minmax(68px, auto)",
        gap: model.layout?.gap || "8px"
      }}
    >
      {sortedTiles.map((tile, index) => {
        const hasSubTiles =
          Array.isArray(tile.SubTiles) && tile.SubTiles.length > 0;

        const tileKey = tile.FilterValue || tile.TileName;
        const isExpanded = expandedTile === tileKey;

        return (
          <div
            key={tileKey}
            className={`dashboard-tile
              ${hasSubTiles ? "has-subtiles" : ""}
              ${isExpanded ? "is-expanded" : ""}
              ${
                model.selectedFilter === tile.FilterValue
                  ? "is-selected"
                  : ""
              }`}
            onClick={(e) => handleTileClick(tile.FilterValue, e)}
          >
            <div className="tile-header-container">
              <TileIcon name={tile.TileName} index={index} />

              <div className="tile-info">
                <div className="tile-name">{tile.TileName}</div>
                <div className="tile-count">{tile.TileCount}</div>
              </div>

              {hasSubTiles ? (
                <button
                  type="button"
                  className={`tile-arrow dropdown-toggle ${
                    isExpanded ? "is-open" : ""
                  }`}
                  aria-label={
                    isExpanded
                      ? `Collapse ${tile.TileName}`
                      : `Expand ${tile.TileName}`
                  }
                  aria-expanded={isExpanded}
                  onClick={(e) => toggleSubTiles(tileKey, e)}
                >
                  <ChevronIcon expanded={isExpanded} />
                </button>
              ) : (
                <div className="tile-arrow" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none">
                    <path
                      d="m9 5 7 7-7 7"
                      stroke="currentColor"
                      strokeWidth="1.8"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </div>
              )}
            </div>

            {hasSubTiles && (
              <div
                className={`sub-tiles-container ${
                  isExpanded ? "is-open" : ""
                }`}
                aria-hidden={!isExpanded}
              >
                {isExpanded &&
                  tile.SubTiles.map((sub) => (
                    <div
                      key={sub.FilterValue || sub.TileName}
                      className={`sub-tile ${
                        model.selectedFilter === sub.FilterValue
                          ? "is-selected"
                          : ""
                      }`}
                      onClick={(e) =>
                        handleTileClick(sub.FilterValue, e)
                      }
                    >
                      <div className="sub-tile-name">
                        {sub.TileName}
                      </div>

                      <div className="sub-tile-count">
                        {sub.TileCount}
                      </div>
                    </div>
                  ))}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

appsmith.onReady(() => {
  ReactDOM.render(
    <App />,
    document.getElementById("root")
  );
});
